write.text:
opt the line is not in stock / sold-out {
  return
}

sequence Cart::total {
  local line: Line
  loop each line {
    self -> line.subtotal() -> part
  }
  return sum
}

sequence Cart::checkout / declined {
  -> total() -> amount
  self -> method.pay(amount) -> paid
  return false
}

diagram SEQ_Declined {
  kind: sequence
  include: shop@store::Cart::checkout / declined
}
